// Auto-generated file banner helper.
//
// Matches the canonical banner shape from tools/ts-codegen/src/lib/file-emit.ts
// so cross-language grep / tooling lights up identically. Two deltas from the
// ts-codegen helper:
//   1. "Generated by" attribution names this pipeline, not ts-codegen.
//   2. Target languages are C#, proto3, and TypeScript — all use "//" comments,
//      so the comment token is fixed (no "#" target in scope for this emitter).

/**
 * Build the standard auto-generated banner for a source file emitted by the
 * TypeSpec emitter fleet.
 *
 * @param sourceSpecPath - Relative path to the `.tsp` spec file that caused
 *   this file to be generated (interpolated into the banner for traceability).
 * @returns Multi-line banner string ending with a blank line, ready to
 *   prepend to any C#, proto3, or TypeScript file.
 */
export function buildBanner(sourceSpecPath: string): string {
  return [
    "// -----------------------------------------------------------------------",
    "// <auto-generated>",
    "//   Generated by the @d2/typespec-emitters TypeSpec emitter.",
    `//   Source spec: ${sourceSpecPath}`,
    "//   Manual edits will be lost on rebuild.",
    "// </auto-generated>",
    "// -----------------------------------------------------------------------",
    "",
  ].join("\n");
}
